#include <cstdlib>
#include "render/VulkanContext.hpp"

namespace orb::gfx {
// MEASUREMENT ONLY (scripts/measure-frame-cost.py): Vulkan timestamp queries,
// four per frame slot -- the start of the frame, the end of the scene, the end
// of the resolve pass, and the end of the frame.
static VkQueryPool gMeasurePool = VK_NULL_HANDLE;
static double gMeasureNsPerTick = 0.0;
static double gMeasureFrameNs = 0.0;
static double gMeasureSceneNs = 0.0;
static double gMeasureResolveNs = 0.0;
static unsigned long long gMeasureSeen = 0;
static unsigned long long gMeasureSamples = 0;
static bool gMeasureWritten[2] = {false, false};
namespace {

if (auto hdr = checkHdrFormat(ctx.physicalDevice_); !hdr) return std::unexpected(hdr.error());
{
    VkPhysicalDeviceProperties props{};
    vkGetPhysicalDeviceProperties(ctx.physicalDevice_, &props);
    gMeasureNsPerTick = static_cast<double>(props.limits.timestampPeriod);
    SDL_Log("MEASURE device vendor=0x%X driver=0x%X api=%u.%u.%u", props.vendorID, props.driverVersion,
            VK_API_VERSION_MAJOR(props.apiVersion), VK_API_VERSION_MINOR(props.apiVersion), VK_API_VERSION_PATCH(props.apiVersion));
    const VkQueryPoolCreateInfo queries{.sType = VK_STRUCTURE_TYPE_QUERY_POOL_CREATE_INFO,
                                        .queryType = VK_QUERY_TYPE_TIMESTAMP, .queryCount = 8};
    static_cast<void>(vkCreateQueryPool(ctx.device_.get(), &queries, nullptr, &gMeasurePool));
    ctx.measurePool_ = OwnedHandle<VkQueryPool, VkDevice, vkDestroyQueryPool>{ctx.device_.get(), gMeasurePool};
}

    return std::unexpected(ok.error());
}
if (gMeasureWritten[frame]) {
    unsigned long long t[4] = {};
    if (vkGetQueryPoolResults(device_.get(), gMeasurePool, frame * 4, 4, sizeof(t), t, 8,
                              VK_QUERY_RESULT_64_BIT) == VK_SUCCESS && ++gMeasureSeen > 500) {
        gMeasureFrameNs += static_cast<double>(t[3] - t[0]) * gMeasureNsPerTick;
        gMeasureSceneNs += static_cast<double>(t[1] - t[0]) * gMeasureNsPerTick;
        gMeasureResolveNs += static_cast<double>(t[2] - t[1]) * gMeasureNsPerTick;
        if (++gMeasureSamples % 500 == 0) {
            const double n = static_cast<double>(gMeasureSamples) * 1000.0;
            SDL_Log("MEASURE timing gpu_frame_us=%.3f scene_us=%.3f resolve_us=%.3f samples=%llu",
                    gMeasureFrameNs / n, gMeasureSceneNs / n, gMeasureResolveNs / n, gMeasureSamples);
        }
    }
}

uint32_t imageIndex = 0;

if (auto ok = beginOneTimeCommandBuffer(cmd); !ok) return std::unexpected(ok.error());
vkCmdResetQueryPool(cmd, gMeasurePool, frame * 4, 4);
vkCmdWriteTimestamp2(cmd, VK_PIPELINE_STAGE_2_TOP_OF_PIPE_BIT, gMeasurePool, frame * 4);
gMeasureWritten[frame] = true;

vkCmdEndRendering(frame.cmd);
vkCmdWriteTimestamp2(frame.cmd, VK_PIPELINE_STAGE_2_ALL_COMMANDS_BIT, gMeasurePool, frame.frameIndex * 4 + 1);
recordResolve(frame, resolve);
vkCmdWriteTimestamp2(frame.cmd, VK_PIPELINE_STAGE_2_ALL_COMMANDS_BIT, gMeasurePool, frame.frameIndex * 4 + 2);

#pragma clang diagnostic ignored "-Weverything" // MEASUREMENT ONLY: never committed
#include "render/ResolvePass.hpp" // SF.5: own header, first
#include <SDL3/SDL_log.h>
#include <chrono>

{
    static double measureNs = 0.0;
    static unsigned long long measureCalls = 0;
    const auto measureStart = std::chrono::steady_clock::now();
    vkUpdateDescriptorSets(device_, 1, &write, 0, nullptr);
    measureNs += static_cast<double>(std::chrono::duration_cast<std::chrono::nanoseconds>(
        std::chrono::steady_clock::now() - measureStart).count());
    if (++measureCalls % 500 == 0) {
        SDL_Log("MEASURE cpu descriptor_update_us=%.4f calls=%llu",
                measureNs / static_cast<double>(measureCalls) / 1000.0, measureCalls);
    }
}
